func argmax(_ values: [Double]) -> Int {
    var best = 0
    for index in values.indices.dropFirst() where values[index] > values[best] { best = index }
    return best
}

func argmin(_ values: [Double]) -> Int {
    var best = 0
    for index in values.indices.dropFirst() where values[index] < values[best] { best = index }
    return best
}
    func scores(_ vector: [Double]) -> [Double] {
        let distances = squaredDistances(vector)
        return means.indices.map { logPriors[$0] - normalizer - logDeterminants[$0] / 2 - distances[$0] / 2 }
    }
    func inferVector(_ vector: [Double], costs: Matrix? = nil) -> Prediction {
        let scores = self.scores(vector)
        let predicted = argmax(scores)
        let maximum = scores[predicted]
        let exponentials = scores.map { exp($0 - maximum) }
        let total = orderedSum(exponentials)
        let probabilities = exponentials.map { $0 / total }
        let logTotal = log(total)
        let logProbabilities = scores.map { ($0 - maximum) - logTotal }
        let decision: Int
        if let costs {
            let risks = means.indices.map { target in orderedSum(means.indices.map { probabilities[$0] * costs[$0][target] }) }
            decision = argmin(risks)
        } else { decision = predicted }
        return Prediction(predicted: predicted, posterior: probabilities, logPosterior: logProbabilities,
                           confidence: probabilities.max()!, decision: decision)
    }

    func infer(_ values: [Double], costs: Matrix? = nil) -> Prediction { inferVector(vector(values), costs: costs) }
func orderedSum<S: Sequence>(_ values: S) -> Double where S.Element == Double {
    var total = 0.0
    for value in values { total += value }
    return total
}
func confusionMatrix(_ actual: [Int], _ predicted: [Int], _ classes: Int) -> [[Int]] {
    var matrix = Array(repeating: Array(repeating: 0, count: classes), count: classes)
    for (expected, prediction) in zip(actual, predicted) { matrix[expected][prediction] += 1 }
    return matrix
}
func measures(_ actual: [Int], _ predicted: [Int], _ classes: Int) -> Measures {
    let matrix = confusionMatrix(actual, predicted, classes)
        results = mainModels.map { model in test.map { model.infer($0.values, costs: data.costs) } }
        predictions = results.map { $0.map { $0.predicted } }
    func modelEvaluation(_ model: Int) -> [String] {
        let results = self.results[model]
        let metrics = measures(testActual, predictions[model], classCount)
        let errors = test.indices.filter { results[$0].predicted != test[$0].classIndex }
        lines.append("errors \(errors.count)")
        lines += errors.map { "error \(test[$0].id) actual \(test[$0].label) predicted \(classes[results[$0].predicted]) confidence \(real(results[$0].confidence))" }
        for threshold in parameters.rejectThresholds {
            let accepted = test.indices.filter { results[$0].confidence >= threshold }
            let correct = accepted.filter { results[$0].predicted == test[$0].classIndex }.count
            lines.append("reject \(real(threshold)) accepted \(accepted.count) coverage \(ratioText(accepted.count, m)) accuracy \(ratioText(correct, accepted.count))")
        }
    func ensemblePredictions() -> [Int] {
        test.indices.map { index in
            argmax(classes.indices.map { group in orderedSum(modelKinds.indices.map { results[$0][index].posterior[group] }) / 3 })
        }
    }
        for model in modelKinds.indices {
            let results = self.results[model]
            let argmaxTotal = orderedSum(test.indices.map { data.costs[test[$0].classIndex][results[$0].predicted] })
            let decisionTotal = orderedSum(test.indices.map { data.costs[test[$0].classIndex][results[$0].decision] })
            let changed = results.filter { $0.predicted != $0.decision }.count
            let correct = test.indices.filter { results[$0].decision == test[$0].classIndex }.count
            lines.append("\(modelKinds[model].rawValue) argmax_total \(real(argmaxTotal)) decision_total \(real(decisionTotal)) "
                + "changed \(changed) decision_accuracy \(ratioText(correct, m))")
        }
